import React, { useState } from 'react';
import './Product.css';
import PageTitle from '../PageTitle';

function Product() {
  const [isModalOpen, setModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  // Ürün bilgilerini bir dizi olarak saklayalım
  const products = [
    { id: 1, name: "Ürün 1", imageUrl: "/path/to/image1.jpg" },
    { id: 2, name: "Ürün 2", imageUrl: "/path/to/image2.jpg" },
    { id: 3, name: "Ürün 3", imageUrl: "/path/to/image3.jpg" },
    { id: 4, name: "Ürün 4", imageUrl: "/path/to/image4.jpg" },
    { id: 5, name: "Ürün 5", imageUrl: "/path/to/image5.jpg" },
    { id: 6, name: "Ürün 6", imageUrl: "/path/to/image6.jpg" },
    { id: 7, name: "Ürün 7", imageUrl: "/path/to/image7.jpg" },
    { id: 8, name: "Ürün 8", imageUrl: "/path/to/image8.jpg" },
  ];

  // Modal'ı açma fonksiyonu
  const openModal = (product) => {
    setSelectedProduct(product);
    setModalOpen(true);
  };

  // Modal'ı kapama fonksiyonu
  const closeModal = () => {
    setModalOpen(false);
    setSelectedProduct(null);
  };

  return (
    <>
    <PageTitle title="Ürünümüz" />
    <div>
            <div   div className="baslik">BİZİ TANIYIN</div>
                <div className="aboutcard">
                    <div className="about-page">
                        <h1 id='about-title'>Hakkımızda</h1>
                        <p>Lorem ipsum dolor, sit amet consectetur adipisicing elit. Nobis hic officiis libero, natus exercitationem reprehenderit, rem repudiandae, similique blanditiis quod aliquid doloremque veritatis deleniti quidem delectus magnam atque laborum omnis?
                            Sunt reprehenderit, quasi voluptatum, aliquam nemo maxime accusantium aut cupiditate dolor inventore cumque? Exercitationem accusamus, quidem quaerat, expedita alias at deleniti praesentium nam asperiores ea ipsum nemo atque corrupti id?
                            Aperiam dignissimos repellat, possimus aliquid beatae voluptatum nobis labore explicabo. Quae similique tenetur eaque obcaecati dolore ex animi quo, voluptate sit reiciendis, quisquam pariatur accusantium, sapiente distinctio excepturi dolores fuga?</p>
                        <div className="about-content">
                        {}
                    </div>
                </div>
            </div>


    </div>
      
      <div className="product-container">
        {products.map((product) => (
          <div className="product-box" key={product.id}>
            <img src={product.imageUrl} alt={product.name} className="product-image" />
            <h3>{product.name}</h3>
            <button onClick={() => openModal(product)}>Detayları Göster</button>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h2>{selectedProduct.name}</h2>
            <img src={selectedProduct.imageUrl} alt={selectedProduct.name} className="product-image" />
            <p>Burada ürünün detayları yer alacak...</p>
            <button onClick={closeModal}>Kapat</button>
          </div>
        </div>
      )}
    </>
  );
}

export default Product;
